/* Backstage: Kök, Yabie presentkort, Kunder, Orderhistorik, Licenser, Lagerhantering. */
(()=>{const {D,B,F,go,INIT,btoast,sub,lbl,inp,ta,dd,OPTHOOK,isOn,tgl,chk,rad,rcard,head,addPill,actPill,foot,BACK,need,SW,swOf,dmy,kr,ibtn,tool,pager,tabs,dlg,openDlg,PG,SAVES,FOOT,pickDlg,pickedTable,addBox,today}=BS;
const STORE=['Kaffebaren'];
/* ── Kök: skrivarstationer ── */
sub('stationform','Lägg till station','stations');BACK.stationform='stations';
PG.stations=()=>{const L=S.stations||[];return head(['Skrivarstationer'],'Skrivarstationer')+`<div class="bsbody"><h2>Ställ in dina skrivarstationer</h2><p class="lead">Konfigurera dina skrivarstationer för att hantera ordrar i köket</p><hr>
 <div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:16px"><div style="width:216px">${lbl('Filtrera på butik')}${dd('b_stf',['Alla butiker',...STORE],'Alla butiker')}</div>${addPill('Lägg till station','stationform','bs-st-add')}</div>
 ${L.map(s=>`<div class="card" style="height:58px" data-g="station-row-${slug(s.name)}"><span class="c1">${esc(s.name)}</span><span class="c3">Kaffebaren</span><span class="act">Aktiv <span class="tgl ${s.active!==false?'on':''}"></span><span class="ms">expand_more</span></span></div>`).join('')}</div>`};
PG.stationform=()=>head(['Skrivarstationer','Lägg till station'],'Lägg till station')+`<div class="bsbody"><h3 style="margin-top:0">Allmänna inställningar</h3><div style="width:284px">${lbl('Namn',1)}${inp('b_sname')}</div><div style="display:flex;align-items:center;gap:8px;font-size:12px;margin-top:10px">Aktiv ${tgl('b_sact',1)}</div><hr>
 <h3 style="margin-top:0">Plats</h3><p class="lead" style="margin-bottom:10px">Välj vilken butik enheten ska placeras i</p><div style="width:284px">${lbl('Butik',1)}${dd('b_sstore',STORE,'Välj butik')}</div><hr>
 <h3 style="margin-top:0">Lägg till produkter</h3><p class="lead" style="margin-bottom:10px">Välj vilka grupper och produkter som ska kopplas</p>${pickedTable('station',580)}<div style="max-width:580px">${addBox('Lägg till produkter','bspick','station','bs-st-prods',!F('b_sstore'))}</div></div>`+pickDlg();
SAVES.stationform=['bssavestation'];
A.bssavestation=()=>{if(!need(['b_sname','b_sstore']))return;const st={name:F('b_sname').trim(),printer:'',gids:[...(UI.f.b_station_g||[])],pids:[...(UI.f.b_station_p||[])],active:isOn('b_sact',1)};
 S.stations=S.stations||[];const ex=S.stations.find(s=>s.name===st.name);if(ex)Object.assign(ex,{gids:st.gids,pids:st.pids,active:st.active});else S.stations.push(st);save();go('stations');btoast('Stationen har skapats');emit('bs:save:station',st)};
/* ── Köksdisplay ── */
sub('kdsform','Lägg till köksdisplay','kds');BACK.kdsform='kds';
PG.kds=()=>{const L=D().kds;return head(['Köksdisplay'],'Köksdisplay')+`<div class="bsbody"><h2>Ställ in dina köksdisplayer</h2><p class="lead" style="max-width:600px">Varje station visar bara sina produkter. En order med en hamburgare och en dryck blir en order i köket för hamburgaren och en order i baren för drycken.</p><div class="rowr">${addPill('Lägg till köksdisplay','kdsform','kds-add')}</div>
 ${L.map(s=>`<div class="card" data-g="kds-row-${slug(s.name)}"><span class="c1">${esc(s.name)}</span><span class="c2">Kaffebaren</span><span class="c3" style="color:#555">${s.gids.map(id=>(G(id)||{}).name).join(', ')}</span><span class="act">Aktiv <span class="tgl on"></span></span></div>`).join('')||'<p class="lead"><i>Inga köksdisplayer ännu.</i></p>'}</div>`};
PG.kdsform=()=>head(['Köksdisplay','Lägg till köksdisplay'],'Lägg till köksdisplay')+`<div class="bsbody"><div style="width:284px">${lbl('Butik',1)}${dd('b_kstore',STORE,'Välj butik')}</div><div style="width:284px;margin-top:12px">${lbl('Namn',1)}${inp('b_kname',{ph:'t.ex. Varmt eller Bar'})}</div><hr><h3 style="margin-top:0">Grupper och produkter</h3><p class="lead" style="margin-bottom:10px">Välj vilka grupper och produkter som ska visas på stationen</p>${pickedTable('kds',580)}<div style="max-width:580px">${addBox('Lägg till produkter','bspick','kds','kds-prods')}</div>
 <div class="info" style="margin-top:16px"><span class="ms">info</span>Logga sedan in i KDS-appen på köksskärmen och välj en ledig licens.</div></div>`+pickDlg();
SAVES.kdsform=['bssavekds'];
A.bssavekds=()=>{if(!need(['b_kstore','b_kname']))return;const k={name:F('b_kname').trim(),gids:[...(UI.f.b_kds_g||[])],pids:[...(UI.f.b_kds_p||[])]};D().kds.push(k);save();go('kds');btoast('Köksdisplayen har skapats');emit('bs:save:kds',k)};
/* ── Rätter ── */
PG.courses=()=>{const L=D().courses;const on=D().set.courses;return head(['Rätter'],'Rätter')+`<div class="bsbody"><h2>Hantera rätter</h2><p class="lead" style="max-width:640px">Rätter delar upp ordern i t.ex. förrätt, varmrätt och dessert. Varje rätt har standardinställningen <b>Servera</b> (skickas direkt till köket) eller <b>Vänta</b>.</p>
 ${on?'':`<div class="warn" style="margin-top:12px"><span class="ms">warning</span><span>Funktionen är avstängd. Slå på <b>Kurshantering</b> under Handlare → Inställningar.</span></div>`}
 <div class="rowr">${actPill('Lägg till ny rätt','bscourse','course-add')}</div><table class="bt" style="max-width:820px"><tr><th>Rätt</th><th>Standard</th><th>Produktgrupper</th></tr>${L.map(c=>`<tr data-g="course-${slug(c.name)}"><td>${esc(c.name)}</td><td><span class="bbdg ${c.def==='serve'?'':'r'}">${c.def==='serve'?'SERVERA':'VÄNTA'}</span></td><td>${c.gids.map(id=>esc((G(id)||{}).name)).join(', ')}</td></tr>`).join('')||'<tr><td colspan="3"><i>Inga rätter ännu</i></td></tr>'}</table>
 ${B().dlg==='course'?dlg('Lägg till ny rätt',`${lbl('Namn',1)}${inp('b_cname',{ph:'t.ex. Förrätter'})}<h3>Standardinställning</h3>${rad('b_cdef','serve','Servera','serve')}${rad('b_cdef','wait','Vänta','serve')}<h3>Produktgrupper</h3><div class="plist">${S.groups.map(g=>`<div>${chk('b_cg_'+g.id,esc(g.name))}</div>`).join('')}</div>`,`<button data-a="bsdlgx">Avbryt</button><button class="p" data-a="bscourseok" data-g="course-save">Spara</button>`):''}</div>`};
A.bscourse=()=>openDlg('course','bs:dlg:course');
A.bscourseok=()=>{if(!need(['b_cname']))return;const c={name:F('b_cname').trim(),def:F('b_cdef')||'serve',gids:S.groups.filter(g=>UI.f['b_cg_'+g.id]).map(g=>g.id)};D().courses.push(c);save();B().dlg=null;render();btoast('Rätten har skapats');emit('bs:save:course',c)};
/* ── Bordskartor (synced with the register's table plans) ── */
sub('planedit','Bordskarta','tableplans');BACK.planedit='tableplans';
PG.tableplans=()=>head(['Bordskartor'],'Bordskartor')+`<div class="bsbody"><h2>Hantera bordskartor</h2><p class="lead" style="max-width:640px">Bordskartorna används i kassan när ordrar parkeras på bord. Ändringar här syns i kassan under Parkerat.</p><div class="rowr">${actPill('Lägg till bordskarta','bsplannew','plan-add')}</div>
 ${(S.plans||[]).map(p=>`<div class="card" data-g="plan-row-${slug(p.name)}"><span class="c1">${esc(p.name)}</span><span class="c2">${p.places.length} bord</span><span class="c3">Kaffebaren</span><span class="act">${ibtn('edit','bsgo','planedit|'+p.id,'plan-edit-'+slug(p.name),'Redigera')}</span></div>`).join('')}</div>`;
A.bsplannew=()=>{S.plans=S.plans||[];const p={id:'pl'+Date.now().toString(36),name:'Ny bordskarta',places:[]};S.plans.push(p);save();go('planedit',p.id);UI.f.b_plname='';render();emit('bs:plannew')};
INIT.planedit=id=>{const p=(S.plans||[]).find(x=>x.id===id);if(p&&p.name!=='Ny bordskarta')UI.f.b_plname=p.name};
PG.planedit=()=>{const p=(S.plans||[]).find(x=>x.id===B().arg);if(!p)return '';const cells=[];const occ={};p.places.forEach(x=>{occ[x.pos]=x});for(let i=0;i<48;i++){const x=occ[i];cells.push(x?`<div class="tb3" style="background:${x.color}" data-g="ptable-${slug(x.name)}">${esc(x.name)}</div>`:`<button data-a="bscell" data-x="${i}" data-g="cell-${i}">+</button>`)}
 return head(['Bordskartor',p.name],'Bordskarta')+`<div class="bsbody"><div style="width:284px">${lbl('Namn på bordskartan',1)}${inp('b_plname',{ph:'t.ex. Matsal'})}</div><p class="lead" style="margin:14px 0 8px">Klicka på en ruta i rutnätet för att skapa ett bord. Håll ned bordet och dra för att flytta det i kassan.</p><div class="bsgrid">${cells.join('')}</div></div>
 ${B().dlg==='cell'?dlg('Lägg till bord',`${lbl('Namn',1)}${inp('b_tname',{ph:'t.ex. Bord 1'})}<h3>Färg</h3><div class="crow" style="flex-wrap:wrap">${SW.slice(1,10).map(s=>`<button data-a="bsrad" data-x="b_tcol|${s[0]}" style="width:26px;height:26px;border-radius:50%;background:${s[1]};${(F('b_tcol')||'Coral')===s[0]?'outline:2px solid #111;outline-offset:2px':''}"></button>`).join('')}</div>`,`<button data-a="bsdlgx">Avbryt</button><button class="p" data-a="bscellok" data-g="cell-ok">OK</button>`,{h:300}):''}`};
SAVES.planedit=['bssaveplan'];
A.bscell=i=>{B().cell=+i;UI.f.b_tname='';UI.f.b_tcol='Coral';openDlg('cell','bs:dlg:cell')};
A.bscellok=()=>{if(!need(['b_tname']))return;const p=S.plans.find(x=>x.id===B().arg);p.places.push({id:'t'+Date.now().toString(36),name:F('b_tname').trim(),color:swOf(F('b_tcol')||'Coral'),pos:B().cell,w:1,h:1});S.tables=S.plans.flatMap(q=>q.places.map(x=>({id:x.id,name:x.name})));save();B().dlg=null;render();emit('bs:table')};
A.bssaveplan=()=>{if(!need(['b_plname']))return;const p=S.plans.find(x=>x.id===B().arg);p.name=F('b_plname').trim();save();go('tableplans');btoast('Bordskartan har sparats');emit('bs:save:plan',p)};
BACK.planedit=()=>{const p=(S.plans||[]).find(x=>x.id===B().arg);if(p&&!p.places.length&&p.name==='Ny bordskarta'){S.plans=S.plans.filter(x=>x!==p);save()}return 'tableplans'};

/* ── Yabie presentkort ── */
sub('gtform','Lägg till ny Yabie presentkortsmall','gtemp');BACK.gtform='gtemp';
const GTPL={Present:'#e5484d',Ballonger:'#3b82f6',Tallrik:'#16a34a',Jul:'#b91c1c'};
PG.gtemp=()=>{const L=D().gtemps;const hasPm=S.payments.some(p=>p.id==='gift'&&p.enabled);return head(['Presentkortsmallar'],'Presentkortsmallar')+`<div class="bsbody"><h2>Yabie presentkort</h2><p class="lead" style="max-width:640px">Skapa mallar för presentkorten du säljer i kassan. När du har lagt till en mall skapas produktgruppen <b>Presentkort</b> automatiskt i kassan.</p>
 ${hasPm?'':`<div class="warn" style="margin-top:12px"><span class="ms">warning</span><span>Lägg först till betalsättet <b>Yabie Presentkort</b> under Betalningar → Betalsätt.</span></div>`}<div class="rowr">${addPill('Lägg till ny Yabie presentkortsmall','gtform','gt-add')}</div>
 <div style="display:flex;gap:14px;flex-wrap:wrap">${L.map(t=>`<div data-g="gt-${slug(t.name)}"><div class="gcard" style="background:${GTPL[t.tpl]}">${esc(t.name)}</div><div style="font-size:11.5px;margin-top:4px">${t.amount?kr(t.amount):'Valfritt belopp'} · ${t.valid} mån</div></div>`).join('')||'<p class="lead"><i>Inga mallar ännu.</i></p>'}</div></div>`};
PG.gtform=()=>head(['Presentkortsmallar','Lägg till ny Yabie presentkortsmall'],'Lägg till ny Yabie presentkortsmall')+`<div class="bsbody"><div style="width:284px">${lbl('Namn',1)}${inp('b_gtname',{ph:'t.ex. Presentkort 200 kr'})}</div><h3>Design</h3><div style="display:flex;gap:12px">${Object.entries(GTPL).map(([n,c])=>`<button data-a="bsrad" data-x="b_gttpl|${n}" data-g="gt-tpl-${slug(n)}" style="text-align:center;font-size:11px"><div class="gcard" style="width:110px;height:70px;font-size:12px;background:${c};${(F('b_gttpl')||'Present')===n?'outline:3px solid #111;outline-offset:2px':''}">${n}</div>${n}</button>`).join('')}</div><div class="note">Mallarna finns också som A4-PDF för utskrift.</div><hr>
 <h3 style="margin-top:0">Belopp</h3>${rad('b_gtamt','fixed','Fast belopp','fixed')}${rad('b_gtamt','free','Valfritt belopp','fixed')}${(F('b_gtamt')||'fixed')==='fixed'?`<div style="width:284px;margin-top:8px">${lbl('Belopp',1)}${inp('b_gtval',{type:'number',ph:'SEK'})}</div>`:''}<hr>
 <div style="width:284px">${lbl('Giltighetstid',1)}${dd('b_gtvalid',[['12','12 månader'],['24','24 månader'],['36','36 månader']],'Välj giltighetstid')}</div></div>`;
SAVES.gtform=['bssavegt'];
A.bssavegt=()=>{const keys=['b_gtname','b_gtvalid'];if((F('b_gtamt')||'fixed')==='fixed')keys.push('b_gtval');if(!need(keys))return;const t={name:F('b_gtname').trim(),tpl:F('b_gttpl')||'Present',amount:(F('b_gtamt')||'fixed')==='fixed'?+F('b_gtval'):0,valid:+F('b_gtvalid')};D().gtemps.push(t);
 let g=S.groups.find(x=>x.name==='Presentkort');if(!g){g={id:'g-gift',name:'Presentkort',vat:0,ledger:'2420',color:'#ffffff'};S.groups.push(g)}if(!S.products.find(p=>p.name===t.name))S.products.push({id:'pg'+Date.now().toString(36),name:t.name,price:t.amount,open:!t.amount,gid:g.id,gift:1});save();go('gtemp');btoast('Mallen har skapats');emit('bs:save:gt',t)};
PG.gover=()=>{const C=D().cards.length?D().cards:[{code:'GC-4821',status:'Aktivt',bal:200,exp:'2027-10-01'},{code:'GC-1934',status:'Aktivt',bal:65,exp:'2027-06-12'},{code:'GC-7710',status:'Utgånget',bal:120,exp:'2026-08-30'},{code:'GC-3302',status:'Makulerat',bal:0,exp:'2027-01-15'}];const act=C.filter(c=>c.status==='Aktivt');
 return head(['Presentkortsöversikt'],'Presentkortsöversikt')+`<div class="bsbody"><div class="kpis" style="grid-template-columns:repeat(2,260px)"><div class="kpi"><small>Aktiva presentkort</small><b>${act.length}</b></div><div class="kpi"><small>Utestående saldo</small><b>${kr(act.reduce((a,c)=>a+c.bal,0))}</b></div></div>
 <div class="tool"><input class="bi sb" placeholder="Sök kod" style="height:28px;font-style:italic"><div class="tb2"><span><span class="ms">tune</span>Filter</span><span data-g="gc-export"><span class="ms">download</span>Exportera CSV</span></div></div>
 <table class="bt"><tr><th>Kod</th><th>Status</th><th>Saldo</th><th>Utgångsdatum</th></tr>${C.map(c=>`<tr><td>${c.code}</td><td><span class="bbdg ${c.status==='Aktivt'?'g':c.status==='Inaktiverat'?'o':'r'}">${c.status.toUpperCase()}</span></td><td>${kr(c.bal)}</td><td>${dmy(c.exp)}</td></tr>`).join('')}</table>
 <div class="note" style="margin-top:12px"><b>Aktivt</b>: oanvänt eller med saldo kvar · <b>Inaktiverat</b>: manuellt inaktiverat · <b>Utgånget</b>: utgångsdatumet har passerat · <b>Makulerat</b>: returnerat av kund</div></div>`};

/* ── Kunder ── */
PG.customers=()=>{const L=D().customers;return head(['Kunder'],'Kunder')+`<div class="bsbody"><h2>Hantera dina kunder</h2><p class="lead">Kunder kan läggas till på ordrar i kassan, t.ex. för faktura eller Fortnox Order.</p><div class="rowr">${actPill('Lägg till ny kund','bscust','cust-add')}</div>${tool('Sök kund','4/4')}
 <table class="bt"><tr><th>Namn</th><th>E-post</th><th>Telefon</th><th style="width:50px"></th></tr>${L.map(c=>`<tr data-g="cust-${slug(c.name)}"><td>${esc(c.name)}</td><td>${esc(c.email)}</td><td>${esc(c.phone)}</td><td><span class="ms" style="font-size:16px">open_in_new</span></td></tr>`).join('')}</table>
 ${B().dlg==='cust'?dlg('Lägg till ny kund',`${lbl('Namn',1)}${inp('b_cuname')}<div style="margin-top:10px">${lbl('Organisationsnummer')}${inp('b_cuorg')}</div><div style="margin-top:10px">${lbl('E-post')}${inp('b_cuemail')}</div><div style="margin-top:10px">${lbl('Telefon')}${inp('b_cuphone')}</div><div style="margin-top:10px">${lbl('Adress')}${inp('b_cuaddr')}</div>`,`<button data-a="bsdlgx">Avbryt</button><button class="p" data-a="bscustok" data-g="cust-save">Spara</button>`):''}</div>`};
A.bscust=()=>openDlg('cust','bs:dlg:cust');
A.bscustok=()=>{if(!need(['b_cuname']))return;const c={name:F('b_cuname').trim(),email:F('b_cuemail'),phone:F('b_cuphone')};D().customers.push(c);save();B().dlg=null;render();btoast('Kunden har lagts till');emit('bs:save:cust',c)};
/* ── Orderhistorik ── */
PG.orders=()=>{const L=S.orders.slice(0,40);return head(['Orderhistorik'],'Orderhistorik')+`<div class="bsbody">${tool('Sök ordernummer','5/5')}<table class="bt"><tr><th>Order</th><th>Datum</th><th>Butik</th><th>Betalsätt</th><th>Summa</th></tr>${L.map(o=>`<tr class="cl" data-a="bsorder" data-x="${o.id}"><td>${esc(o.id)}</td><td>${esc(o.at)}</td><td>Kaffebaren</td><td>${esc((o.history[0]||{}).method||'')}</td><td>${kr(o.total)}</td></tr>`).join('')||'<tr><td colspan="5"><i>Inga ordrar ännu. Sälj något i kassan så syns det här.</i></td></tr>'}</table>${pager(L.length)}
 ${B().dlg==='order'?(()=>{const o=S.orders.find(x=>x.id===B().ord);return dlg('Order '+esc(o.id),`<table class="bt"><tr><th>Artikel</th><th>Antal</th><th>Summa</th></tr>${o.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.qty}</td><td>${kr(lineTot(i))}</td></tr>`).join('')}</table><p style="text-align:right;font-weight:700;margin-top:10px">Totalt ${kr(o.total)}</p>`,`<button data-a="bsdlgx">Stäng</button>`)})():''}</div>`};
A.bsorder=id=>{B().ord=id;openDlg('order','bs:dlg:order')};
/* ── Licenser ── */
PG.licenses=()=>head(['Licenser'],'Licenser')+`<div class="bsbody"><h2>Hantera dina licenser</h2><p class="lead">Se och hantera dina licenser och deras status</p><hr>
 <div class="tool" style="justify-content:flex-end"><div class="tb2"><span><span class="ms">tune</span>Filter</span><span><span class="ms">view_column</span>Kolumner <small style="color:#888">5/5</small></span></div></div>
 <table class="bt"><tr><th>Butik</th><th>Kassa</th><th>Licens</th><th>Kassanamn</th><th>Enhet</th><th>Aktiv appversion</th><th>Status</th></tr><tr class="gr"><td colspan="6">Kaffebaren</td><td style="text-align:right"><span class="ms">expand_less</span></td></tr>
 <tr data-g="lic-1"><td></td><td>101</td><td><small style="color:#666">EXPRESS</small><br><span class="ms" style="font-size:13px">content_copy</span> 7F3A....9C21</td><td>${esc(S.register)}</td><td>iPad</td><td>3.38.1</td><td><span class="bbdg g">AKTIV</span></td></tr>
 ${D().kds.map((k,i)=>`<tr><td></td><td>${102+i}</td><td><small style="color:#666">KDS</small><br><span class="ms" style="font-size:13px">content_copy</span> 2B9${i}....E07D</td><td>${esc(k.name)}</td><td>iPad</td><td>3.38.1</td><td><span class="bbdg g">AKTIV</span></td></tr>`).join('')}</table></div>`;

/* ── Lagerhantering ── */
const stocked=()=>S.products.filter(p=>p.stock);
sub('stakenew','Ny inventering','stake');sub('stakerun','Inventering','stake');sub('smovenew','Ny lagerförflyttning','smove');Object.assign(BACK,{stakenew:'stake',stakerun:'stake',smovenew:'smove'});
PG.stake=()=>{const L=D().stockTakes;return head(['Inventering'],'Inventering')+`<div class="bsbody"><h2>Inventering</h2><p class="lead" style="max-width:600px">Räkna lagret och jämför med lagersaldot. En fullständig inventering omfattar alla produkter med lagerhantering.</p><div class="rowr">${addPill('Ny inventering','stakenew','stake-add')}</div>
 <table class="bt"><tr><th>Namn</th><th>Plats</th><th>Personal</th><th>Status</th><th style="width:110px"></th></tr>${L.map((s,i)=>`<tr data-g="stake-${slug(s.name)}"><td>${esc(s.name)}</td><td>${esc(s.loc)}</td><td>${esc(s.who)}</td><td><span class="bbdg ${s.done?'g':'o'}">${s.done?'SLUTFÖRD':'PÅBÖRJAD'}</span></td><td>${s.done?ibtn('summarize','bsstakerep',i,'stake-rep-'+i,'Lagerrapport'):ibtn('play_arrow','bsgo','stakerun|'+i,'stake-open-'+i,'Fortsätt')}</td></tr>`).join('')||'<tr><td colspan="5"><i>Inga inventeringar ännu</i></td></tr>'}</table>
 ${B().dlg==='srep'?(()=>{const s=L[B().srep];return dlg('Lagerrapport: '+esc(s.name),`<table class="bt"><tr><th>Produkt</th><th>Förväntat</th><th>Räknat</th><th>Avvikelse</th><th>Anledning</th></tr>${s.rows.map(r=>`<tr><td>${esc((P(r.pid)||{}).name)}</td><td>${r.exp}</td><td>${r.cnt}</td><td>${r.cnt-r.exp}</td><td>${esc(r.why||'')}</td></tr>`).join('')}</table>`,`<button data-a="bsdlgx">Stäng</button><button class="p" data-a="bsexport" data-g="srep-export">Exportera</button>`,{wide:1})})():''}</div>`};
A.bsstakerep=i=>{B().srep=+i;openDlg('srep','bs:dlg:srep')};
A.bsexport=()=>{btoast('Rapporten har exporterats');emit('bs:export')};
PG.stakenew=()=>head(['Inventering','Ny inventering'],'Ny inventering')+`<div class="bsbody"><div style="width:360px">${lbl('Namn',1)}${inp('b_stname',{ph:'t.ex. Q4 Lagerinventering - Kaffebaren'})}</div><div class="grid2" style="margin-top:12px"><div>${lbl('Personal',1)}${dd('b_stwho',D().users.map(u=>u.first+' '+u.last),'Välj personal')}</div><div>${lbl('Plats',1)}${dd('b_stloc',D().locations.map(l=>l.name),'Välj plats')}</div></div><hr>
 <h3 style="margin-top:0">Omfattning</h3><div class="grid2" style="grid-template-columns:358px 358px">${rcard('b_stscope','part','Delvis inventering','Välj vilka artiklar eller ingredienser som ska räknas','full')}${rcard('b_stscope','full','Fullständig inventering','Alla produkter med lagerhantering aktiverad','full')}</div>
 ${!stocked().length?`<div class="warn" style="margin-top:14px"><span class="ms">warning</span>Inga produkter har lagerhantering aktiverad. Aktivera den under produktens flik Lager.</div>`:''}</div>`;
FOOT.stakenew=()=>`<div class="bsfoot"><button class="bcan" data-a="bscancel" data-g="bs-cancel">Avbryt</button><button class="bnext ok" data-a="bsstakecreate" data-g="stake-create">Skapa lagerinventering</button></div>`;
A.bsstakecreate=()=>{if(!need(['b_stname','b_stwho','b_stloc']))return;const L=stocked();if(!L.length){btoast('Aktivera lagerhantering på minst en produkt först');return}
 const s={name:F('b_stname').trim(),who:F('b_stwho'),loc:F('b_stloc'),rows:L.map(p=>({pid:p.id,exp:p.stock.qty,cnt:null,why:''})),done:false};D().stockTakes.unshift(s);save();go('stakerun','0');emit('bs:stake:create')};
PG.stakerun=()=>{const s=D().stockTakes[+B().arg];return head(['Inventering',s.name],esc(s.name))+`<div class="bsbody"><p class="lead">${esc(s.loc)} · ${esc(s.who)} · <span class="bbdg o">PÅBÖRJAD</span></p><table class="bt" style="margin-top:12px"><tr><th>Produkt</th><th>Förväntat lagersaldo</th><th>Räknat</th><th style="width:130px"></th></tr>${s.rows.map((r,i)=>`<tr data-g="srow-${slug((P(r.pid)||{}).name)}"><td>${esc((P(r.pid)||{}).name)}</td><td>${r.exp}</td><td>${r.cnt==null?'-':r.cnt}${r.why?` <small style="color:#9a5b00">(${esc(r.why)})</small>`:''}</td><td>${ibtn('calculate','bscount',i,'count-'+slug((P(r.pid)||{}).name),'Räkna artikel')}</td></tr>`).join('')}</table>
 ${B().dlg==='count'?(()=>{const r=s.rows[B().cnt];const diff=F('b_cnt')!==''&&+F('b_cnt')!==r.exp;return dlg('Räkna artikel',`<b>${esc((P(r.pid)||{}).name)}</b><p class="lead">Förväntat lagersaldo: ${r.exp}</p><div style="margin-top:10px">${lbl('Räknat antal',1)}${inp('b_cnt',{type:'number',live:1})}</div>${diff?`<div style="margin-top:10px">${lbl('Anledning till avvikelse',1)}${dd('b_cwhy',['Svinn','Felregistrering','Skadad vara','Stöld','Övrigt'],'Välj anledning')}</div>`:''}`,`<button data-a="bsdlgx">Avbryt</button><button class="p" data-a="bscountok" data-g="count-ok">Spara</button>`,{h:340})})():''}</div>`};
FOOT.stakerun=()=>`<div class="bsfoot"><button class="bcan" data-a="bsgo" data-x="stake" data-g="stake-close">Stäng</button><button class="bnext ok" data-a="bsstakedone" data-g="stake-done">Slutför inventering</button></div>`;
A.bscount=i=>{B().cnt=+i;UI.f.b_cnt='';UI.f.b_cwhy='';openDlg('count','bs:dlg:count')};
A.bscountok=()=>{const s=D().stockTakes[+B().arg];const r=s.rows[B().cnt];if(!need(['b_cnt']))return;const n=+F('b_cnt');if(n!==r.exp&&!need(['b_cnt','b_cwhy']))return;r.cnt=n;r.why=n!==r.exp?F('b_cwhy'):'';save();B().dlg=null;render();emit('bs:count')};
A.bsstakedone=()=>{const s=D().stockTakes[+B().arg];if(s.rows.some(r=>r.cnt==null)){btoast('Räkna alla produkter först');return}s.rows.forEach(r=>{const p=P(r.pid);if(p&&p.stock){if(r.cnt!==p.stock.qty)p.stock.log.unshift({at:today(),d:r.cnt-p.stock.qty,who:s.who,why:'Inventering'});p.stock.qty=r.cnt}});s.done=true;save();go('stake');btoast('Inventeringen är slutförd');emit('bs:stake:done')};
PG.smove=()=>{const L=D().transfers;return head(['Lagerförflyttning'],'Lagerförflyttningar')+`<div class="bsbody"><div class="rowr" style="margin-top:0">${addPill('Ny lagerförflyttning','smovenew','smove-add')}</div><table class="bt"><tr><th>Från</th><th>Till</th><th>Produkter</th><th>Status</th><th style="width:40px"></th></tr>${L.map((t,i)=>`<tr data-g="move-${i}"><td>${esc(t.from)}</td><td>${esc(t.to)}</td><td>${t.rows.map(r=>r.qty+' × '+esc((P(r.pid)||{}).name)).join(', ')}</td><td><span class="bbdg ${t.done?'g':'o'}">${t.done?'LEVERERAD':'PÅGÅENDE'}</span></td><td>${t.done?'':`<button data-a="bsmovemenu" data-x="${i}" data-g="move-dots-${i}" class="ms">more_vert</button>`}</td></tr>`).join('')||'<tr><td colspan="5"><i>Inga lagerförflyttningar ännu</i></td></tr>'}</table>
 ${B().dlg==='movem'?dlg('Lagerförflyttning',`<p class="lead">Markera förflyttningen som färdig när varorna har kommit fram. Lagersaldot uppdateras i den mottagande butiken.</p>`,`<button data-a="bsdlgx">Avbryt</button><button class="p" data-a="bsmovedone" data-g="move-done">Markera som färdig</button>`,{h:220}):''}</div>`};
A.bsmovemenu=i=>{B().mv=+i;openDlg('movem','bs:dlg:movem')};
A.bsmovedone=()=>{const t=D().transfers[B().mv];t.done=true;t.at=today();save();B().dlg=null;render();btoast('Leveransen är registrerad');emit('bs:move:done')};
INIT.smovenew=()=>{UI.f.b_mvrows=[]};
PG.smovenew=()=>{const rows=UI.f.b_mvrows||[];const rev=B().mvrev;const locs=D().locations.map(l=>l.name);return head(['Lagerförflyttning','Ny lagerförflyttning'],'Ny lagerförflyttning')+`<div class="bsbody">${rev?`<h2>Granska</h2><div class="sum" style="width:420px"><b>${esc(F('b_mvfrom'))} → ${esc(F('b_mvto'))}</b><br>${esc(F('b_mvwho'))} · ${esc(F('b_mvwhy'))}<br>${rows.map(r=>r.qty+' × '+esc((P(r.pid)||{}).name)).join('<br>')}</div>`:`
 <div class="grid2"><div>${lbl('Från',1)}${dd('b_mvfrom',locs,'Välj plats')}</div><div>${lbl('Till',1)}${dd('b_mvto',locs,'Välj plats')}</div><div>${lbl('Personal',1)}${dd('b_mvwho',D().users.map(u=>u.first+' '+u.last),'Välj personal')}</div><div>${lbl('Anledning',1)}${dd('b_mvwhy',['Påfyllning','Omfördelning','Retur till lager'],'Välj anledning')}</div></div><hr>
 <h3 style="margin-top:0">Produkter</h3>${rows.length?`<table class="bt" style="max-width:580px;margin-bottom:10px"><tr><th>Produkt</th><th>Antal</th></tr>${rows.map(r=>`<tr><td>${esc((P(r.pid)||{}).name)}</td><td>${r.qty}</td></tr>`).join('')}</table>`:''}
 <div class="crow" style="max-width:580px"><div style="flex:1">${dd('b_mvpid',stocked().map(p=>[p.id,p.name]),'Välj produkt')}</div><div style="width:90px">${inp('b_mvqty',{type:'number',ph:'Antal'})}</div>${actPill('Lägg till','bsmvadd','mv-add')}</div>${!stocked().length?'<div class="note">Aktivera lagerhantering på produkterna först.</div>':''}`}</div>`};
FOOT.smovenew=()=>`<div class="bsfoot"><button class="bcan" data-a="${B().mvrev?'bsmvback':'bscancel'}" data-g="bs-cancel">${B().mvrev?'Tillbaka':'Avbryt'}</button><button class="bnext ok" data-a="${B().mvrev?'bsmvfinish':'bsmvreview'}" data-g="${B().mvrev?'mv-finish':'mv-review'}">${B().mvrev?'Slutför lagerförflyttning':'Granska'}</button></div>`;
A.bsmvadd=()=>{if(!need(['b_mvpid','b_mvqty']))return;(UI.f.b_mvrows=UI.f.b_mvrows||[]).push({pid:F('b_mvpid'),qty:+F('b_mvqty')});UI.f.b_mvpid='';UI.f.b_mvqty='';render();emit('bs:mvadd')};
A.bsmvreview=()=>{if(!need(['b_mvfrom','b_mvto','b_mvwho','b_mvwhy']))return;if(F('b_mvfrom')===F('b_mvto')){btoast('Välj två olika platser');return}if(!(UI.f.b_mvrows||[]).length){btoast('Lägg till minst en produkt');return}B().mvrev=1;render();emit('bs:mvreview')};
A.bsmvback=()=>{B().mvrev=0;render()};
A.bsmvfinish=()=>{D().transfers.unshift({from:F('b_mvfrom'),to:F('b_mvto'),who:F('b_mvwho'),why:F('b_mvwhy'),rows:[...UI.f.b_mvrows],done:false});B().mvrev=0;save();go('smove');btoast('Lagerförflyttningen har skapats med status Pågående');emit('bs:move:create')};
PG.srec=()=>{const L=D().transfers.filter(t=>t.done);return head(['Leveranser'],'Leveranser')+`<div class="bsbody"><p class="lead">Mottagna lagerförflyttningar.</p><table class="bt" style="margin-top:12px"><tr><th>Datum</th><th>Från</th><th>Till</th><th>Produkter</th></tr>${L.map(t=>`<tr><td>${dmy(t.at)}</td><td>${esc(t.from)}</td><td>${esc(t.to)}</td><td>${t.rows.map(r=>r.qty+' × '+esc((P(r.pid)||{}).name)).join(', ')}</td></tr>`).join('')||'<tr><td colspan="4"><i>Inga leveranser ännu</i></td></tr>'}</table></div>`};
const REPS=[['level','Lagernivå','Totalt lager med antal, inköpspris, lagervärde och moms'],['hist','Historiskt lager','Lagernivåer ett valt datum'],['low','Lågt lagersaldo','Produkter som nått sin gräns för lågt lagersaldo'],['nonsell','Icke säljande produkter','Lagervaror som inte sålts under en vald period'],['dev','Lageravvikelse','Skillnader mellan lagersaldo och inventering'],['chg','Lagerändringar','Alla justeringar, påfyllningar och förflyttningar']];
PG.srep=()=>{const r=B().srepT;return head(['Lagerrapporter'],'Lagerrapporter')+`<div class="bsbody"><div class="tile3">${REPS.map(([k,t,d])=>`<button data-a="bssrep" data-x="${k}" data-g="srep-${k}" style="${r===k?'border-color:#111':''}"><b>${t}</b>${d}</button>`).join('')}</div>
 ${r?`<hr><div style="display:flex;justify-content:space-between"><h2>${REPS.find(x=>x[0]===r)[1]}</h2>${actPill('Exportera','bsexport','srep-export','','download')}</div><table class="bt" style="margin-top:10px"><tr><th>Produkt</th><th>Lagersaldo</th><th>Gräns</th><th>Lagervärde</th></tr>${stocked().filter(p=>r!=='low'||p.stock.low&&p.stock.qty<=p.stock.limit).map(p=>`<tr><td>${esc(p.name)}</td><td>${p.stock.qty}</td><td>${p.stock.low?p.stock.limit:'-'}</td><td>${kr(p.stock.qty*p.price*0.4)}</td></tr>`).join('')||'<tr><td colspan="4"><i>Inga produkter</i></td></tr>'}</table>`:''}</div>`};
A.bssrep=k=>{B().srepT=k;render();emit('bs:srep:'+k)};
PG.sloc=()=>head(['Lagerplatser'],'Lagerplatser')+`<div class="bsbody"><h2>Lagerhantering per butik</h2><p class="lead" style="max-width:600px">Slå av lagerhanteringen i butiker där du inte vill följa lagret, t.ex. tillfälliga pop up-butiker.</p><table class="bt" style="max-width:720px;margin-top:12px"><tr><th>Plats</th><th>Typ</th><th>Lagerhantering</th></tr>${D().locations.map((l,i)=>`<tr data-g="loc-${slug(l.name)}"><td>${esc(l.name)}</td><td>${l.wh?'Lagerplats':'Butik'}</td><td><button class="tgl ${l.stock?'on':''}" data-a="bsloctg" data-x="${i}" data-g="loc-tg-${slug(l.name)}"></button></td></tr>`).join('')}</table></div>`;
A.bsloctg=i=>{const l=D().locations[+i];l.stock=!l.stock;save();render();emit('bs:loctg')};

/* ── verified against Backstage (sv), Oct 2026 ── */
PG.stations=()=>{const L=S.stations||[];return head(['Skrivarstationer'],'Skrivarstationer')+`<div class="bsbody"><h2>Konfigurera dina skrivarstationer</h2><p class="lead">Konfigurera dina skrivarstationer för att hantera beställningar i köket</p><hr>
 <div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:16px"><div style="width:216px">${lbl('Filtrera på butik')}${dd('b_stf',['Alla butiker',...STORE],'Alla butiker')}</div>${addPill('Lägg till station','stationform','bs-st-add')}</div>
 ${L.map(s=>`<div class="card" style="height:58px" data-g="station-row-${slug(s.name)}"><span class="c1">${esc(s.name)}</span><span class="c3">Kaffebaren</span><span class="act">Aktiv <span class="tgl ${s.active!==false?'on':''}"></span><span class="ms">expand_more</span></span></div>`).join('')}</div>`};
const devForm=(trail,title,k,x,g)=>head([trail,title],title)+`<div class="bsbody"><h3 style="margin-top:0">Allmänna inställningar</h3><div style="width:284px">${lbl('Namn',1)}${inp('b_'+k+'name')}</div><div style="display:flex;align-items:center;gap:8px;font-size:12px;margin-top:10px">Aktiv ${tgl('b_'+k+'act',1)}</div><hr>
 <h3 style="margin-top:0">Plats</h3><p class="lead" style="margin-bottom:10px">Välj vilken butik som denna enhet ska placeras i</p><div style="width:284px">${lbl('Butik',1)}${dd('b_'+k+'store',STORE,'Välj butik')}</div><hr>
 <h3 style="margin-top:0">Lägg till produkter</h3><p class="lead" style="margin-bottom:10px">Välj de grupper och produkter som ska kopplas</p>${pickedTable(x,580)}<div style="max-width:580px">${addBox('Lägg till produkter','bspick',x,g,!F('b_'+k+'store'))}</div></div>`+pickDlg();
PG.stationform=()=>devForm('Skrivarstationer','Lägg till station','s','station','bs-st-prods');
PG.kds=()=>{const L=D().kds;return head(['Köksdisplay'],'Köksdisplay')+`<div class="bsbody"><h2>Konfigurera dina köksdisplayer</h2><p class="lead">Konfigurera dina köksdisplayer för att hantera beställningar i köket</p><hr>
 <div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:16px"><div style="width:216px">${lbl('Filtrera på butik')}${dd('b_kf',['Alla butiker',...STORE],'Alla butiker')}</div>${addPill('Lägg till köksdisplay','kdsform','kds-add')}</div>
 ${L.map(s=>`<div class="card" style="height:58px" data-g="kds-row-${slug(s.name)}"><span class="c1">${esc(s.name)}</span><span class="c3">Kaffebaren</span><span class="act">Aktiv <span class="tgl on"></span><span class="ms">expand_more</span></span></div>`).join('')}${pager(L.length)}</div>`};
PG.kdsform=()=>devForm('Köksdisplay','Lägg till köksdisplay','k','kds','kds-prods');
A.bssavekds=()=>{if(!need(['b_kname','b_kstore']))return;const k={name:F('b_kname').trim(),gids:[...(UI.f.b_kds_g||[])],pids:[...(UI.f.b_kds_p||[])]};D().kds.push(k);save();go('kds');btoast('Köksdisplayen har skapats');emit('bs:save:kds',k)};
/* Rätter: list + page form */
sub('courseform','Skapa ny rätt','courses');BACK.courseform='courses';
PG.courses=()=>{const L=D().courses;const on=D().set.courses;return head(['Rätter'],'Rätter')+`<div class="bsbody"><h2>Hantera dina rätter</h2><p class="lead" style="max-width:640px">Här kan du hantera dina rätter och kategorisera dem så att köket kan förbereda dem i rätt ordning</p>
 ${on?'':`<div class="warn" style="margin-top:12px"><span class="ms">warning</span><span>Funktionen är avstängd. Slå på <b>Hantering av rätter (Fram/Vänta)</b> under Handlare → Inställningar.</span></div>`}<hr>
 <div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:16px"><div style="width:216px">${lbl('Filtrera på butik')}${dd('b_cf',['Alla butiker',...STORE],'Alla butiker')}</div>${addPill('Skapa ny rätt','courseform','course-add')}</div>
 ${L.map(c=>`<div class="card" data-g="course-${slug(c.name)}"><span class="c1"><span style="opacity:.4">⠿</span>${esc(c.name)}</span><span class="c2">Kaffebaren</span><span class="c3"><span class="bbdg ${c.def==='serve'?'':'r'}">${c.def==='serve'?'SERVERA':'VÄNTA'}</span></span><span class="act"><span class="ms">expand_more</span></span></div>`).join('')||'<p class="lead"><i>Inga rätter ännu.</i></p>'}</div>`};
PG.courseform=()=>head(['Rätter','Skapa ny rätt'],'Skapa ny rätt')+`<div class="bsbody"><h3 style="margin-top:0">Allmänna inställningar</h3><div style="width:284px">${lbl('Namn',1)}${inp('b_cname')}</div><hr class="d">
 <h3 style="margin-top:0">Plats</h3><p class="lead" style="margin-bottom:10px">Välj vart rätten ska vara tillgänglig</p><div style="width:284px">${lbl('Plats',1)}${dd('b_cstore',STORE,'Välj plats')}</div><hr class="d">
 <h3 style="margin-top:0">Standardinställning</h3>${rad('b_cdef','wait','Vänta','wait')}${rad('b_cdef','serve','Fram','wait')}<hr class="d">
 <h3 style="margin-top:0">Lägg till produktgrupper</h3><p class="lead" style="margin-bottom:10px">Välj vilka produktgrupper som ska ingå i rätten</p>${pickedTable('course',580)}<div style="max-width:580px">${addBox('Lägg till produktgrupper','bspick','course','course-groups')}</div></div>`+pickDlg();
SAVES.courseform=['bssavecourse'];
A.bssavecourse=()=>{if(!need(['b_cname','b_cstore']))return;const c={name:F('b_cname').trim(),def:F('b_cdef')||'wait',gids:[...(UI.f.b_course_g||[])]};D().courses.push(c);save();go('courses');btoast('Rätten har skapats');emit('bs:save:course',c)};
/* Bordskartor */
PG.tableplans=()=>head(['Bordskartor'],'Bordskartor')+`<div class="bsbody"><div class="warn"><span class="ms">warning</span>Du behöver app-version 3.35 eller senare på alla kassor för att kunna hantera bordskartor i Backstage.</div><h2>Hantera dina bordskartor</h2><p class="lead" style="max-width:700px">Ordna bord i ett rutnät genom att ändra deras storlek och position, och ändra ordningen i bordlistan. OBS: Dina parkerade ordrar kan endast hanteras i kassan. Här hanterar du endast bordskartor.</p><hr>
 <div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:16px"><div style="width:216px">${lbl('Filtrera på butik')}${dd('b_tpf',['Alla butiker',...STORE],'Alla butiker')}</div>${actPill('Skapa bordskarta','bsplannew','plan-add')}</div>
 ${(S.plans||[]).map(p=>`<div class="card" data-g="plan-row-${slug(p.name)}"><span class="c1">${esc(p.name)}</span><span class="c2">Kaffebaren</span><span class="c3">${p.places.length} bord</span><span class="act">${ibtn('edit','bsgo','planedit|'+p.id,'plan-edit-'+slug(p.name),'Redigera')}</span></div>`).join('')}</div>`;
sub('planedit','Skapa bordskarta','tableplans');
const _pe=PG.planedit;PG.planedit=()=>{const h=_pe();return h.replace(/<div class="bshead"[^]*?<\/h1><\/div>/,head(['Bordskartor','Skapa bordskarta'],'Skapa bordskarta')).replace(`<div style="width:284px">${lbl('Namn på bordskartan',1)}${inp('b_plname',{ph:'t.ex. Matsal'})}</div>`,`<div class="grid2"><div>${lbl('Bordskartanamn',1)}${inp('b_plname')}</div><div>${lbl('Butik',1)}${dd('b_plstore',STORE,'Välj butik')}</div></div><div style="width:284px;margin-top:12px">${lbl('Visa som')}${dd('b_plview',['Rutnät','Lista'],'Rutnät')}</div>`)};
/* Presentkort */
PG.gtemp=()=>{const L=D().gtemps;const hasPm=S.payments.some(p=>p.id==='gift'&&p.enabled);return head(['Presentkortsmallar'],'Presentkortsmallar')+`<div class="bsbody"><h2>Skapa mallar för presentkort</h2><p class="lead" style="max-width:640px">Presentkortsmallar visas som produkter i kassan som kunderna kan köpa och sedan använda i din butik. Mallarna kan antingen ha ett fast pris eller ett öppet pris med ett maxbelopp.</p>
 ${hasPm?'':`<div class="warn" style="margin-top:12px"><span class="ms">warning</span><span>Lägg först till betalsättet <b>Yabie Presentkort</b> under Betalningar → Betalsätt.</span></div>`}<div class="rowr">${addPill('Lägg till ny Yabie presentkortsmall','gtform','gt-add')}</div>
 <table class="bt"><tr><th>Namn</th><th>Pristyp</th><th>Pris</th><th>Giltighetstid</th><th>Skuldkonto</th><th>Intäktskonto</th><th>Status</th></tr>${L.map(t=>`<tr data-g="gt-${slug(t.name)}"><td>${esc(t.name)}</td><td>${t.amount?'Fast pris':'Öppet pris'}</td><td>${t.amount?kr(t.amount):kr(t.min||0)+' - '+kr(t.max||0)}</td><td>${t.valid} år</td><td>${esc(t.debt||'2420')}</td><td>${esc(t.inc||'3690')}</td><td><span class="bbdg g">AKTIV</span></td></tr>`).join('')||'<tr><td colspan="7"><i>Inga mallar ännu</i></td></tr>'}</table></div>`};
sub('gtform','Skapa ny Yabie presentkortsmall','gtemp');
PG.gtform=()=>head(['Presentkortsmallar','Skapa ny Yabie presentkortsmall'],'Skapa ny Yabie presentkortsmall')+`<div class="bsbody"><h3 style="margin-top:0">Namn</h3><p class="lead">Namnet visas bara för presentkortsprodukten i kassan och visas inte på det sålda presentkortet</p><div style="width:284px;margin-top:8px">${lbl('Namn',1)}${inp('b_gtname')}</div><hr class="d"><button class="pill" style="opacity:.5"><span class="ms" style="background:#999">add</span>Lägg till översättning</button><hr>
 <h3 style="margin-top:0">Giltighet</h3><div class="crow"><div style="width:284px">${lbl('Giltighetstid',1)}${dd('b_gtvalid',[['1','1 år'],['2','2 år'],['3','3 år'],['5','5 år']],'1 år')}</div><div style="display:flex;gap:8px;align-items:center;font-size:12px;margin-top:16px">${tgl('b_gtact',1)}Aktiv (Yabie presentkort är tillgängliga för försäljning)</div></div><hr>
 <h3 style="margin-top:0">Pris</h3>${lbl('Pristyp',1)}${rad('b_gtamt','fixed','Fast pris','open')}${rad('b_gtamt','open','Öppet pris','open')}<div class="grid2" style="margin-top:10px">${(F('b_gtamt')||'open')==='fixed'?`<div>${lbl('Pris inkl. moms',1)}${inp('b_gtval',{type:'number',ph:'SEK'})}</div>`:`<div>${lbl('Lägsta pris inkl. moms')}${inp('b_gtmin',{type:'number',ph:'SEK'})}</div><div>${lbl('Högsta pris inkl. moms',1)}${inp('b_gtmax',{type:'number',ph:'SEK'})}</div>`}</div><hr>
 <h3 style="margin-top:0">Bokföringskonton</h3><div class="grid2"><div>${lbl('Skuldkonto')}${inp('b_gtdebt',{ph:'2420'})}</div><div>${lbl('Intäktskonto')}${inp('b_gtinc',{ph:'3690'})}<div class="help">(Används för Yabie presentkort som gått ut med värde kvar)</div></div></div><hr>
 <h3 style="margin-top:0">Bild</h3><p class="lead">Bilden visas bara för presentkortsprodukten i kassan och visas inte på det sålda presentkortet</p><div style="width:300px;margin-top:8px">${lbl('Bild som visas i kassan')}<div class="imgbox"><div><span class="ms">add_photo_alternate</span><br>Dra bilden hit eller klicka för att välja en fil</div></div></div></div>`;
A.bssavegt=()=>{const fixed=(F('b_gtamt')||'open')==='fixed';const keys=['b_gtname'];keys.push(fixed?'b_gtval':'b_gtmax');if(!need(keys))return;const t={name:F('b_gtname').trim(),amount:fixed?+F('b_gtval'):0,min:+F('b_gtmin')||0,max:+F('b_gtmax')||0,valid:+(F('b_gtvalid')||1),debt:F('b_gtdebt')||'2420',inc:F('b_gtinc')||'3690'};D().gtemps.push(t);
 let g=S.groups.find(x=>x.name==='Presentkort');if(!g){g={id:'g-gift',name:'Presentkort',vat:0,ledger:'2420',color:'#ffffff'};S.groups.push(g)}if(!S.products.find(p=>p.name===t.name))S.products.push({id:'pg'+Date.now().toString(36),name:t.name,price:t.amount,open:!t.amount,gid:g.id,gift:1});save();go('gtemp');btoast('Mallen har skapats');emit('bs:save:gt',t)};
PG.gover=()=>{const C=D().cards.length?D().cards:[{name:'Presentkort',no:'736968898532',cust:'-',status:'AKTIVT',at:'2026-10-05',exp:'2027-10-05',bal:200},{name:'Presentkort',no:'293747745244',cust:'-',status:'AKTIVT',at:'2026-09-09',exp:'2027-09-09',bal:65},{name:'Presentkort',no:'497089299355',cust:'-',status:'MAKULERAT',at:'2026-08-04',exp:'2027-08-04',bal:0},{name:'Presentkort',no:'856496779078',cust:'-',status:'UTGÅNGET',at:'2025-08-30',exp:'2026-08-30',bal:120}];const act=C.filter(c=>c.status==='AKTIVT');
 return head(['Presentkortsöversikt'],'Presentkortsöversikt')+`<div class="bsbody"><h2>Sammanfattning av presentkort</h2><p class="lead" style="max-width:520px">Få en komplett överblick över dina presentkort. Se statusändringar, utgångsdatum och kvarvarande saldon för att ha full kontroll över utestående skulder.</p>
 <div style="display:flex;gap:12px;margin:16px 0"><div style="background:#e3fbef;border-radius:6px;padding:14px 18px;font-size:12px;line-height:1.8"><b>Totalt antal aktiva presentkort:</b> ${act.length} st<br><b>Totalt värde aktiva presentkort:</b> ${kr(act.reduce((a,c)=>a+c.bal,0))}</div><div style="background:#ffeedb;border-radius:6px;padding:14px 18px;font-size:12px;line-height:1.8"><b>Totalt antal frysta presentkort:</b> 0 st<br><b>Totalt värde frysta presentkort:</b> ${kr(0)}</div></div>
 <div class="rowr">${actPill('Ladda ner CSV','bsexport','gc-export','','download')}</div>${BS.tool('Sök på telefon, email eller serienummer','6/6')}
 <table class="bt dk"><tr><th>Namn</th><th>Serienummer</th><th>Kund</th><th>Status</th><th>Datum för statusändring</th><th>Giltigt till</th><th>Värde</th></tr>${C.map(c=>`<tr><td>${esc(c.name)}</td><td>${c.no}</td><td>${c.cust}</td><td><span class="bbdg ${c.status==='AKTIVT'?'g':'r'}">${c.status}</span></td><td>${c.at}</td><td>${c.exp}</td><td>${kr(c.bal)}</td></tr>`).join('')}</table></div>`};
/* Kunder och orderhistorik */
PG.customers=()=>head(['Kunder'],'Kunder')+`<div class="bsbody"><h2>Hantera din kundlista</h2><p class="lead" style="max-width:600px">Visa och hantera information om dina kunder. Du kan både lägga till företag och privatpersoner som kunder.</p><div class="info" style="margin-top:14px;max-width:760px"><span class="ms">info</span>Du kan bara se dina kunder i kassan eller på integrationsplattformen eftersom integrationen konfigureras i organisationen.</div></div>`;
PG.orders=()=>{const L=S.orders.slice(0,40);return head(['Orderhistorik'],'Orderhistorik')+`<div class="bsbody"><div class="tool"><input class="bi sb" placeholder="Sök" style="height:28px;font-style:italic"><span style="background:#f1f1f1;padding:6px 12px;font-size:11px;color:#1677c9">${BS.today()}</span><div class="tb2"><span><span class="ms">tune</span>Filter</span><span><span class="ms">view_column</span>Kolumner <small style="color:#888">7/7</small></span></div></div><table class="bt"><tr><th>Datum &amp; Tid</th><th>Ordernummer</th><th>Butik</th><th>Kassa</th><th>Bord</th><th>Kund</th><th>Totalt betalt belopp</th><th>Betalsätt</th></tr>${L.map(o=>`<tr class="cl" data-a="bsorder" data-x="${o.id}"><td>${esc(o.at)}</td><td>${esc(o.id)}</td><td>Kaffebaren</td><td>${esc(S.register)}</td><td>${esc(o.table||'-')}</td><td>${esc(o.customer||'-')}</td><td>${kr(o.total)}</td><td>${esc((o.history[0]||{}).method||'')}</td></tr>`).join('')}</table>${L.length?'':'<p class="lead" style="margin-top:8px">Visar 0 av totalt 0 resultat. Sälj något i kassan så syns det här.</p>'}
 ${B().dlg==='order'?(()=>{const o=S.orders.find(x=>x.id===B().ord);return dlg('Order '+esc(o.id),`<table class="bt"><tr><th>Artikel</th><th>Antal</th><th>Summa</th></tr>${o.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.qty}</td><td>${kr(lineTot(i))}</td></tr>`).join('')}</table><p style="text-align:right;font-weight:700;margin-top:10px">Totalt ${kr(o.total)}</p>`,`<button data-a="bsdlgx">Stäng</button>`)})():''}</div>`};
/* Lager */
PG.stake=()=>{const L=D().stockTakes;return head(['Inventering'],'Inventering')+`<div class="bsbody"><h2>Skapa listor för inventering</h2><p class="lead" style="max-width:600px">Skapa och hantera listor för att genomföra inventeringar och hålla koll på ditt lagersaldo</p><hr>
 <div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:14px"><div class="crow" style="margin:0"><div style="width:180px">${lbl('Plats')}${dd('b_stkf',['Alla',...D().locations.map(l=>l.name)],'Alla')}</div></div>${addPill('Ny inventering','stakenew','stake-add')}</div>
 ${L.map((s,i)=>`<div class="card" data-g="stake-${slug(s.name)}"><span class="c1">${esc(s.name)}</span><span class="c2">${s.at||BS.today()}</span><span class="c3"><span class="bbdg ${s.done?'g':'o'}">${s.done?'SLUTFÖRD':'PÅBÖRJAD'}</span></span><span class="act">${s.done?ibtn('summarize','bsstakerep',i,'stake-rep-'+i,'Lagerrapport'):ibtn('more_vert','bsgo','stakerun|'+i,'stake-open-'+i,'Funktioner')}<span class="ms">expand_more</span></span></div>`).join('')||'<p class="lead"><i>Inga inventeringar ännu.</i></p>'}
 ${B().dlg==='srep'?(()=>{const s=L[B().srep];return dlg('Lagerrapport: '+esc(s.name),`<table class="bt"><tr><th>Produkt</th><th>Förväntat</th><th>Räknat</th><th>Avvikelse</th><th>Anledning</th></tr>${s.rows.map(r=>`<tr><td>${esc((P(r.pid)||{}).name)}</td><td>${r.exp}</td><td>${r.cnt}</td><td>${r.cnt-r.exp}</td><td>${esc(r.why||'')}</td></tr>`).join('')}</table>`,`<button data-a="bsdlgx">Stäng</button><button class="p" data-a="bsexport" data-g="srep-export">Ladda ner</button>`,{wide:1})})():''}</div>`};
PG.stakenew=()=>`<div class="bshead"><div class="bc">${BS.org()} / Inventering</div><div class="steps"><span class="c">1</span></div></div><div class="bsbody"><h1 style="margin:0 0 8px;font:800 24px Inter,sans-serif">Ny inventering</h1><p class="lead">Skapa en ny inventering för att räkna och uppdatera ditt lager</p><hr><h3 style="margin-top:0">Allmänna inställningar</h3><div style="width:584px">${lbl('Inventeringsnamn',1)}${inp('b_stname',{ph:'Inventeringsnamn'})}</div><div class="grid2" style="margin-top:12px"><div>${lbl('Personal',1)}${dd('b_stwho',D().users.map(u=>u.first+' '+u.last),'Välj personal')}</div><div>${lbl('Plats',1)}${dd('b_stloc',D().locations.map(l=>l.name),'Välj plats')}</div></div><hr>
 <h3 style="margin-top:0">Hur vill du inventera</h3>${rad('b_stscope','part','Delvis inventering','part')}${rad('b_stscope','full','Fullständig inventering','part')}<div style="margin-top:8px">${lbl('Vad vill du räkna')}${rad('b_stwhat','prod','Produkter','prod')}${rad('b_stwhat','ing','Ingredienser','prod')}</div>
 ${(F('b_stscope')||'part')==='part'?`<div style="margin-top:10px;max-width:584px">${pickedTable('stake',584)}${addBox('Lägg till produkter','bspick','stake','stake-prods')}<div class="note">Ange produkter som ska ingå i inventeringen</div></div>`:'<div class="note">Alla produkter med lagerhantering aktiverad ingår.</div>'}
 ${!S.products.some(p=>p.stock)?`<div class="warn" style="margin-top:14px"><span class="ms">warning</span>Inga produkter har lagerhantering aktiverad. Aktivera den under produktens flik Lager.</div>`:''}</div>`+pickDlg();
FOOT.stakenew=()=>`<div class="bsfoot" style="justify-content:flex-end;gap:10px"><button class="bnext" data-a="bscancel" data-g="bs-cancel">Avbryt</button><button class="bnext ok" data-a="bsstakecreate" data-g="stake-create">Skapa inventering<span class="ms" style="font-size:17px">chevron_right</span></button></div>`;
A.bsstakecreate=()=>{if(!need(['b_stname','b_stwho','b_stloc']))return;const part=(F('b_stscope')||'part')==='part';let L=S.products.filter(p=>p.stock);if(part){const g=UI.f.b_stake_g||[],pp=UI.f.b_stake_p||[];L=L.filter(p=>g.includes(p.gid)||pp.includes(p.id))}if(!L.length){btoast(part?'Lägg till produkter med lagerhantering':'Aktivera lagerhantering på minst en produkt först');return}
 const s={name:F('b_stname').trim(),who:F('b_stwho'),loc:F('b_stloc'),at:BS.today(),rows:L.map(p=>({pid:p.id,exp:p.stock.qty,cnt:null,why:''})),done:false};D().stockTakes.unshift(s);save();go('stakerun','0');emit('bs:stake:create')};
/* Lagerförflyttning → Leveranser (mottagning) */
PG.smove=()=>{const L=D().transfers;return head(['Lagerförflyttning'],'Lagerförflyttning')+`<div class="bsbody"><h2>Flytta produkter mellan dina butiker</h2><p class="lead" style="max-width:640px">Här väljer du vilka produkter du vill flytta och mellan vilka platser. När din lagerförflyttning är markerad som färdig kan du följa den på sidan för leveranser.</p><hr>
 <div style="display:flex;justify-content:space-between;margin-bottom:14px"><span class="pill" style="background:#fff;border:1px solid #ccc"><span class="ms" style="background:none;color:#111">tune</span>Filtrera lista</span>${addPill('Ny lagerförflyttning','smovenew','smove-add')}</div>
 ${L.map((t,i)=>`<div class="card" data-g="move-${i}"><span class="c1">${esc(t.from)} → ${esc(t.to)}</span><span class="c2">${t.at||BS.today()}</span><span class="c3">${t.rows.reduce((a,r)=>a+r.qty,0)} Artiklar</span><span class="act"><span class="bbdg ${t.done?'g':'o'}">${t.done?'FÄRDIG':'PÅGÅENDE'}</span>${t.done?'':`<button data-a="bsmovemenu" data-x="${i}" data-g="move-dots-${i}" class="ms">more_vert</button>`}<span class="ms">expand_more</span></span></div>`).join('')||'<p class="lead"><i>Inga lagerförflyttningar ännu.</i></p>'}
 ${B().dlg==='movem'?dlg('Lagerförflyttning',`<p class="lead">Markera förflyttningen som färdig när varorna har skickats. Mottagaren räknar och tar emot leveransen under Leveranser.</p>`,`<button data-a="bsdlgx">Avbryt</button><button class="p" data-a="bsmovedone" data-g="move-done">Markera som färdig</button>`,{h:220}):''}</div>`};
A.bsmovedone=()=>{const t=D().transfers[B().mv];t.done=true;t.at=BS.today();t.recv=false;save();B().dlg=null;render();btoast('Lagerförflyttningen är markerad som färdig');emit('bs:move:done')};
PG.smovenew=()=>{const rows=UI.f.b_mvrows||[];const rev=B().mvrev;const locs=D().locations.map(l=>l.name);return `<div class="bshead"><div class="bc">${BS.org()} / Lagerförflyttning / Ny lagerförflyttning</div><div class="steps"><span class="${rev?'d':'c'}">1</span><span class="${rev?'c':''}">2</span></div></div><div class="bsbody">${rev?`<h1 style="margin:0 0 8px;font:800 24px Inter,sans-serif">Granska</h1><div class="sum" style="width:420px"><b>${esc(F('b_mvfrom'))} → ${esc(F('b_mvto'))}</b><br>${esc(F('b_mvwho'))} · ${esc(F('b_mvwhy'))}<br>${rows.map(r=>r.qty+' × '+esc((P(r.pid)||{}).name)).join('<br>')}</div>`:`
 <h1 style="margin:0 0 8px;font:800 24px Inter,sans-serif">Välj vad som ska flyttas och vart</h1><p class="lead">Ange detaljerna för din lagerflytt. I det nästa steget kan du granska att allt ser bra ut innan du utför flytten.</p><hr><h3 style="margin-top:0">Plats</h3>
 <div class="grid2"><div>${lbl('Flytta lager från',1)}${dd('b_mvfrom',locs,'Välj plats')}</div><div>${lbl('Flytta lager till',1)}${dd('b_mvto',locs,'Välj plats')}</div></div><h3>Vem och varför</h3><div class="grid2"><div>${lbl('Personal',1)}${dd('b_mvwho',D().users.map(u=>u.first+' '+u.last),'Välj personal')}</div><div>${lbl('Anledning',1)}${dd('b_mvwhy',['Påfyllning','Omfördelning','Retur till lager'],'Välj anledning')}</div></div><hr>
 <h3 style="margin-top:0">Välj artiklar att flytta</h3>${rad('b_mvwhat','prod','Produkter','prod')}${rad('b_mvwhat','ing','Ingredienser','prod')}${rows.length?`<table class="bt" style="max-width:584px;margin:10px 0"><tr><th>Produkt</th><th>Antal</th></tr>${rows.map(r=>`<tr><td>${esc((P(r.pid)||{}).name)}</td><td>${r.qty}</td></tr>`).join('')}</table>`:''}
 <div class="crow" style="max-width:584px;margin-top:10px"><div style="flex:1">${dd('b_mvpid',S.products.filter(p=>p.stock).map(p=>[p.id,p.name]),'Välj produkt')}</div><div style="width:90px">${inp('b_mvqty',{type:'number',ph:'Antal'})}</div>${actPill('Lägg till','bsmvadd','mv-add')}</div>`}</div>`};
FOOT.smovenew=()=>`<div class="bsfoot" style="justify-content:flex-end;gap:10px"><button class="bnext" style="width:210px" data-a="${B().mvrev?'bsmvback':'bscancel'}" data-g="bs-cancel">${B().mvrev?'Föregående':'Avbryt lagerförflyttning'}</button><button class="bnext ok" data-a="${B().mvrev?'bsmvfinish':'bsmvreview'}" data-g="${B().mvrev?'mv-finish':'mv-review'}">${B().mvrev?'Slutför lagerförflyttning':'Granska'}<span class="ms" style="font-size:17px">chevron_right</span></button></div>`;
A.bsmvfinish=()=>{D().transfers.unshift({from:F('b_mvfrom'),to:F('b_mvto'),who:F('b_mvwho'),why:F('b_mvwhy'),rows:[...UI.f.b_mvrows],done:false,at:BS.today()});B().mvrev=0;save();go('smove');btoast('Lagerförflyttningen har skapats');emit('bs:move:create')};
PG.srec=()=>{const L=D().transfers.filter(t=>t.done);return head(['Leveranser'],'Leveranser')+`<div class="bsbody"><h2>Hantera inkommande leveranser och lagerförflyttningar</h2><p class="lead" style="max-width:660px">Här kan du räkna artiklar i leveranser och markera dem som mottagna. När en leverans är markerad som mottagen så uppdateras ditt lagersaldo med det mottagna antalet produkter.</p><hr>
 ${L.map((t,i)=>`<div class="card" data-g="rec-${i}"><span class="c1">${esc(t.from)} → ${esc(t.to)}</span><span class="c2">${t.at}</span><span class="c3">${t.rows.length} produkter</span><span class="act"><span class="bbdg ${t.recv?'g':'o'}">${t.recv?'MOTTAGET':'VÄNTAR'}</span>${t.recv?'':ibtn('inventory','bsrecv',D().transfers.indexOf(t),'rec-recv-'+i,'Ta emot')}</span></div>`).join('')||'<p class="lead"><i>Inga leveranser ännu.</i></p>'}</div>`};
A.bsrecv=i=>{const t=D().transfers[+i];t.recv=true;t.rows.forEach(r=>{const p=P(r.pid);if(p&&p.stock){p.stock.qty+=r.qty;p.stock.log.unshift({at:BS.today(),d:r.qty,who:t.who,why:'Leverans'})}});save();render();btoast('Leveransen är mottagen och lagersaldot har uppdaterats');emit('bs:recv')};
const REPT=[['level','Lagernivå'],['hist','Historisk lager'],['low','Lågt lagersaldo'],['nonsell','Icke säljande produkter'],['dev','Lageravvikelse'],['chg','Lagerändringar']];
PG.srep=()=>{const r=B().srepT||'level';const L=S.products.filter(p=>p.stock).filter(p=>r!=='low'||p.stock.low&&p.stock.qty<=p.stock.limit);return head(['Lagerrapporter'],'Lagerrapporter')+`<div class="bsbody"><h2>Sammanställningar av lagerdata</h2><p class="lead" style="max-width:560px">Se detaljerad information om ditt lager, inklusive lagersaldo, värde och rörelser. Filtera, sök och ladda ner dina rapporter.</p>
 <div class="btabs">${REPT.map(([k,t])=>`<button class="${r===k?'on':''}" data-a="bssrep" data-x="${k}" data-g="srep-${k}">${t}</button>`).join('')}</div><div class="rowr" style="margin-top:0">${actPill('Ladda ner rapport','bsexport','srep-export','','download')}</div>${BS.tool('Sök på produktnamn, SKU eller EAN...','10/10')}
 <table class="bt dk"><tr><th>Produktnamn ▲</th><th>Produktgrupp</th><th>Plats</th><th>Aktuellt lagersaldo</th><th>Inköpspris exkl. moms</th><th>Försäljningspris exkl. moms</th><th>Total kostnad ex moms</th></tr>${L.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc((G(p.gid)||{}).name)}</td><td>Kaffebaren</td><td>${p.stock.qty}</td><td>${kr(p.price*0.4)}</td><td>${kr(p.price*0.8)}</td><td>${kr(p.stock.qty*p.price*0.4)}</td></tr>`).join('')||'<tr><td colspan="7"><i>Inga produkter</i></td></tr>'}</table></div>`};
PG.sloc=()=>head(['Lagerplatser'],'Lagerplatser')+`<div class="bsbody"><h2>Platser för lagerhantering</h2><p class="lead" style="max-width:600px">Välj vilka platser du vill använda för lagerhantering. När en butik eller lagerplats blivit aktiverad kan du lagerföra artiklar där.</p><hr>${D().locations.map((l,i)=>`<div class="card" data-g="loc-${slug(l.name)}"><span class="c1">${esc(l.name)}</span><span class="c2">${l.wh?'Lagerplats':'Butik'}</span><span class="c3"><span class="bbdg ${l.stock?'g':'r'}">${l.stock?'AKTIV':'INAKTIV'}</span></span><span class="act"><button class="tgl ${l.stock?'on':''}" data-a="bsloctg" data-x="${i}" data-g="loc-tg-${slug(l.name)}"></button><span class="ms">expand_more</span></span></div>`).join('')}</div>`;
})();
